use crate::types::{FocusCandidate,Point2};
use std::f32::consts::PI;
#[derive(Clone,Copy,Debug)] pub struct FocusTrackerConfig{pub alpha:f32,pub beta:f32,pub latency_ms:f32,pub horizontal_fov_deg:f32,pub vertical_fov_deg:f32}
impl Default for FocusTrackerConfig{fn default()->Self{Self{alpha:0.65,beta:0.08,latency_ms:50.0,horizontal_fov_deg:70.0,vertical_fov_deg:50.0}}}
#[derive(Clone,Debug)] pub struct FocusTracker{cfg:FocusTrackerConfig,pos:Point2,vel:Point2,initialized:bool}
impl FocusTracker{pub fn new(cfg:FocusTrackerConfig)->Self{Self{cfg,pos:Point2::new(0.5,0.5),vel:Point2::new(0.0,0.0),initialized:false}}pub fn fuse(candidates:&[FocusCandidate])->Option<Point2>{let(mut sx,mut sy,mut sw)=(0.0,0.0,0.0);for c in candidates{let w=c.effective_weight();if w<=0.0{continue;}let p=c.point.clamped();sx+=p.x*w;sy+=p.y*w;sw+=w;}if sw>0.0{Some(Point2::new(sx/sw,sy/sw).clamped())}else{None}}pub fn update(&mut self,measurement:Point2,dt_s:f32)->Point2{let dt=dt_s.max(1e-4);let z=measurement.clamped();if !self.initialized{self.pos=z;self.vel=Point2::new(0.0,0.0);self.initialized=true;return self.predicted();}let pred=Point2::new(self.pos.x+self.vel.x*dt,self.pos.y+self.vel.y*dt);let rx=z.x-pred.x;let ry=z.y-pred.y;let a=self.cfg.alpha.clamp(0.0,1.0);let b=self.cfg.beta.max(0.0);self.pos=Point2::new(pred.x+a*rx,pred.y+a*ry).clamped();self.vel=Point2::new(self.vel.x+(b/dt)*rx,self.vel.y+(b/dt)*ry);self.predicted()}pub fn predicted(&self)->Point2{let h=(self.cfg.latency_ms.max(0.0)/1000.0).min(0.5);Point2::new(self.pos.x+self.vel.x*h,self.pos.y+self.vel.y*h).clamped()}pub fn compensate_imu(&self,p:Point2,gyro_yaw_rad_s:f32,gyro_pitch_rad_s:f32,dt_s:f32)->Point2{let hfov=self.cfg.horizontal_fov_deg.max(1.0)*PI/180.0;let vfov=self.cfg.vertical_fov_deg.max(1.0)*PI/180.0;let tx=(hfov*0.5).tan();let ty=(vfov*0.5).tan();let px=(2.0*p.x.clamp(0.0,1.0)-1.0)*tx;let py=(2.0*p.y.clamp(0.0,1.0)-1.0)*ty;let ax=px.atan()-gyro_yaw_rad_s*dt_s;let ay=py.atan()+gyro_pitch_rad_s*dt_s;Point2::new(0.5*(ax.tan()/tx+1.0),0.5*(ay.tan()/ty+1.0)).clamped()}}
#[cfg(test)]mod tests{use super::*;#[test]fn weighted_fusion(){let p=FocusTracker::fuse(&[FocusCandidate{point:Point2::new(0.0,0.5),confidence:1.0,weight:1.0},FocusCandidate{point:Point2::new(1.0,0.5),confidence:1.0,weight:3.0}]).unwrap();assert!((p.x-0.75).abs()<1e-5);}}
